import{_ as e,o as n,c as r,a5 as i}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"手动脱壳：找 OEP、Dump 与修 IAT","description":"当没有现成脱壳工具时，需要手动脱壳。完整流程分三步，无论什么壳都逃不出这个框架：找 OEP → dump 内存 → 修 IAT。这一章逐步拆解。","frontmatter":{"type":"explanation","level":"advanced"},"headers":[],"relativePath":"reverse-engineering/07-packing/chapter-02-manual-unpacking.md","filePath":"reverse-engineering/07-packing/chapter-02-manual-unpacking.md"}'),c={name:"reverse-engineering/07-packing/chapter-02-manual-unpacking.md"};function t(p,a,l,d,g,s){return n(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="手动脱壳-找-oep、dump-与修-iat" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">手动脱壳：找 OEP、Dump 与修 IAT <a class="header-anchor" href="#手动脱壳-找-oep、dump-与修-iat" aria-label="Permalink to &quot;手动脱壳：找 OEP、Dump 与修 IAT&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">当没有现成脱壳工具时，需要手动脱壳。完整流程分三步，无论什么壳都逃不出这个框架：<strong>找 OEP → dump 内存 → 修 IAT</strong>。这一章逐步拆解。</p><h2 id="_1-第一步-找-oep" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">1. 第一步：找 OEP <a class="header-anchor" href="#_1-第一步-找-oep" aria-label="Permalink to &quot;1. 第一步：找 OEP&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">让程序运行到「壳已还原、即将跳原始入口」的那一瞬间，就是 OEP。常用三种方法：</p><p data-src-line="10" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md"><strong>ESP 定律</strong>（最常用）。壳的 stub 开头常有 <code>pushad</code>/<code>pushfd</code>（保存所有寄存器），此时对栈顶 <code>ESP</code> 下<strong>硬件断点</strong>（访问），然后 <code>F9</code> 运行。壳还原完成后会 <code>popad</code> 恢复寄存器并访问栈，命中硬件断点停下，附近往往就是跳向 OEP 的 <code>jmp</code>。</p><p data-src-line="12" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md"><strong>单步跟踪</strong>。从壳入口一路单步，直到出现一次<strong>大范围跳转</strong>（跨节区的 <code>jmp</code>），那个目标常是 OEP。这个方法慢，但能看清壳的还原过程。</p><p data-src-line="14" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md"><strong>内存断点法</strong>。对 <code>UPX0</code> 这类「运行时才填充」的节下内存访问断点，命中时壳已解压完成。</p><p data-src-line="16" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">三种方法的共同思路是：<strong>抓住「壳还原完成」这个信号</strong>——无论是寄存器被恢复、还是代码段被填充、还是发生跨节区跳转。</p><h2 id="_2-第二步-dump-内存" tabindex="-1" data-src-line="18" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">2. 第二步：dump 内存 <a class="header-anchor" href="#_2-第二步-dump-内存" aria-label="Permalink to &quot;2. 第二步：dump 内存&quot;">​</a></h2><p data-src-line="20" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">停在 OEP 后，此刻内存里已经是完整的、还原后的程序。用调试器的 dump 功能（x64dbg 的 Scylla 插件，或 OllyDbg 时代的 OllyDump）把当前进程镜像 dump 出来，存成新的文件。</p><p data-src-line="22" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">关键点：<strong>必须在 OEP 处 dump</strong>，因为只有此刻，内存里的代码和数据才是「已还原」的完整状态。dump 早了，代码还没解压完；dump 晚了，程序可能已经进入运行状态、内存被改动。</p><h2 id="_3-第三步-修复导入表" tabindex="-1" data-src-line="24" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">3. 第三步：修复导入表 <a class="header-anchor" href="#_3-第三步-修复导入表" aria-label="Permalink to &quot;3. 第三步：修复导入表&quot;">​</a></h2><p data-src-line="26" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">dump 出来的文件有个问题：它的导入表（IAT）里的函数地址是「当前运行时的真实地址」，脱离这个进程环境就失效了（因为 ASLR，下次运行的基址不同，这些地址不再有效）。</p><p data-src-line="28" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">需要用 <strong>Scylla（或 ImportREC）</strong> 分析 dump 文件、重建导入表：</p><ol data-src-line="30" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md"><li data-src-line="30" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">让 Scylla 定位 dump 文件里的 IAT。</li><li data-src-line="31" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">Scylla 扫描 IAT 里的函数地址，反查它们属于哪个 DLL 的哪个函数。</li><li data-src-line="32" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">重建导入表，把「运行时地址」换回「函数名/序号」，恢复成正常的 PE 结构。</li></ol><p data-src-line="34" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">三步做完，你就得到一个「脱壳后的程序」，可以用 <a href="./../05-static-analysis/chapter-04-ida-pro.html">IDA Pro</a> 或 <a href="./../05-static-analysis/chapter-05-ghidra.html">Ghidra</a> 正常分析了。</p><h2 id="_4-练习建议" tabindex="-1" data-src-line="36" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">4. 练习建议 <a class="header-anchor" href="#_4-练习建议" aria-label="Permalink to &quot;4. 练习建议&quot;">​</a></h2><p data-src-line="38" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">手动脱壳是逆向的中级技能，第一次做几乎必然在「找 OEP」或「修 IAT」卡住。建议按这个顺序练习：</p><ol data-src-line="40" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md"><li data-src-line="40" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">先用 UPX 加壳一个自己写的程序。</li><li data-src-line="41" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">用 <code>upx -d</code> 脱一次，确认「脱壳后的正确结果」长什么样。</li><li data-src-line="42" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">再手动脱一次（ESP 定律找 OEP → dump → Scylla 修 IAT），对照自动脱壳的结果。</li></ol><p data-src-line="44" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">体会每一步在做什么，再挑战更复杂的壳。</p><hr><blockquote data-src-line="48" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md"><p data-src-line="48" data-src-file="reverse-engineering/07-packing/chapter-02-manual-unpacking.md">本章走通了手动脱壳的完整流程：找 OEP、dump 内存、修 IAT。这三步是所有脱壳方法的核心。下一章进入更难的方向——<a href="./chapter-03-virtualization-anti-debugging.html">虚拟化保护与反调试</a>。</p></blockquote>',22)])])}const o=e(c,[["render",t]]);export{m as __pageData,o as default};
